// Bit-exact validation micro-probe TEMPLATE (torch-free, NCU-able, standalone).
//
// Use this to validate a fragile layout/PTX recipe (swizzle, wgmma descriptor,
// register-fragment permute, transpose) against a CPU oracle BEFORE wiring it
// into fa3_fwd.cu. A recipe that is not bit-exact here will not be correct in
// the kernel. Model after kernels/fp8_probe.cu and kernels/mainloop_micro.cu.
//
// Build: A="-gencode arch=compute_90a,code=sm_90a"
//        nvcc -O3 -std=c++17 $A kernels/<your_probe>.cu -o /tmp/probe && /tmp/probe
//
// Exit code 0 == bit-exact. Non-zero == mismatch (do NOT integrate).

#include "oracle_common.cuh"   // orc::fill_bf16, f32_to_bf16_bits, bf16_bits_to_f32, ORC_CHECK, benchmark_ms

// ------------------------------------------------------------------------
// 1) CANDIDATE: the exact device recipe you intend to paste into fa3_fwd.cu.
//    Copy the real helpers (koff/koff8, make_smem_desc, qk_doff, the wgmma
//    asm) verbatim so the probe tests the SAME instructions, not a paraphrase.
// ------------------------------------------------------------------------
__global__ void candidate_kernel(const uint16_t* __restrict__ in,
                                 float* __restrict__ out /*, params */) {
    // TODO: implement the recipe. Write the computed result (e.g. the QK/PV
    // accumulator, or the transposed/swizzled tile read back linearly) to out.
}

// ------------------------------------------------------------------------
// 2) ORACLE: the same math on the CPU, in fp32, with NO shortcuts. This is
//    ground truth. For softmax use ex2/round-to-nearest to match bit-exactly
//    (see recipes.md bit-exactness rules); for a plain GEMM, fp32 accumulate.
// ------------------------------------------------------------------------
static void cpu_oracle(const std::vector<uint16_t>& in,
                       std::vector<float>& ref /*, params */) {
    // TODO: compute ref[i] the canonical way.
}

int main(int argc, char** argv) {
    // --- problem size (edit to your tile) ---
    const int M = 64, N = 128, K = 128;
    const size_t n_in = size_t(M) * K + size_t(N) * K;   // e.g. A[MxK] + B[NxK]
    const size_t n_out = size_t(M) * N;

    std::vector<uint16_t> h_in;
    orc::fill_bf16(h_in, n_in, /*seed=*/1234);

    uint16_t* d_in = nullptr; float* d_out = nullptr;
    ORC_CHECK(cudaMalloc(&d_in, n_in * sizeof(uint16_t)));
    ORC_CHECK(cudaMalloc(&d_out, n_out * sizeof(float)));
    ORC_CHECK(cudaMemcpy(d_in, h_in.data(), n_in * sizeof(uint16_t), cudaMemcpyHostToDevice));

    candidate_kernel<<</*grid*/1, /*block*/128, /*smem*/0>>>(d_in, d_out);
    ORC_CHECK(cudaGetLastError());
    ORC_CHECK(cudaDeviceSynchronize());

    std::vector<float> got(n_out), ref(n_out);
    ORC_CHECK(cudaMemcpy(got.data(), d_out, n_out * sizeof(float), cudaMemcpyDeviceToHost));
    cpu_oracle(h_in, ref);

    // --- compare: report exact-mismatch count AND max ulp/abs error ---
    size_t bad = 0; float maxabs = 0.f;
    for (size_t i = 0; i < n_out; ++i) {
        float d = std::fabs(got[i] - ref[i]);
        maxabs = std::max(maxabs, d);
        if (got[i] != ref[i]) ++bad;   // bit-exact check; loosen to `d > tol` if only tol-parity is needed
    }
    std::printf("mismatch %zu/%zu  max_abs_err %.3e\n", bad, n_out, maxabs);
    ORC_CHECK(cudaFree(d_in)); ORC_CHECK(cudaFree(d_out));
    return bad == 0 ? 0 : 1;
}
